sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {


    //Parameterise the URL, and build the endpoint
    try {
        gs.info('Bulk Redesign - oubtound BR triggered.');
        // var instanceURI = gs.getProperty('glide.servlet.uri');
        // var requestEndpoint = instanceURI + '/api/x_hsb11_mss_c_ghss/ghss_request';
        // var user = gs.getProperty("HSBC_BasicAuthentication_UserName");
        // var password = gs.getProperty("HSBC_BasicAuthentication_Password");
        // var request = new sn_ws.RESTMessageV2();
        // request.setBasicAuth(user, password);
        // request.setEndpoint(requestEndpoint);
        // request.setHttpMethod('POST');
        var isRedesign = gs.getProperty('x_hsb11_mss_c_proc.mssCustodyLinkTradesForBulk');
        var outcome = current.bulk_id.outcome;
        var bulkType = current.bulk_id.bulk_type;
        gs.info('Bulk Redesign - Line 17 Redesign ' + isRedesign + ' outcome ' + outcome + ' bulk type ' + bulkType);
        if (isRedesign.indexOf('true') > -1 && bulkType.indexOf('manual_task') > -1 && outcome.indexOf('Amend') < 0) {
            gs.info('Bulk Redesign - Line 18');
            var checkerName = current.bulk_id.u_current_checker_assignee.user_name.toString();
            var checkerId = checkerName.slice(0, 8);
            var makerName = current.bulk_id.current_maker_assignee.user_name.toString();
            var makerId = makerName.slice(0, 8);
            gs.info('Checker Id ' + checkerId + ' maker Id ' + makerId);

        } else {
            var checkerName = current.trade_case_id.current_checker_assignee.user_name.toString();
            var checkerId = checkerName.slice(0, 8);
            var makerName = current.trade_case_id.current_maker_assignee.user_name.toString();
            var makerId = makerName.slice(0, 8);
        }

        var sourceSystem = current.trade_id.source_system.toString();
        var trdOwningBusiness = current.trade_id.owning_business.toString();

        var ghssSourceSystem = gs.getProperty('x_hsb11_mss_c_ghss.hsbcGHSSWidgetTriggerSourceSystem');
        var gcsSourceSystem = gs.getProperty('x_hsb11_mss_c_ghss.hsbcGCSWidgetTriggerSourceSystem');
        var swiftSource = gs.getProperty('x_hsb11_mss_c_proc.hsbcmss_el_custody_source_system_swift_populate_swift_exception');


        var adviceType = "";
        var adviceTypeGCS = "";
        var suspendType = "";
        var collectChargeIndicator = "";
        var s = "";
        var autoResumeIndicator = "";
        var valDateValue = null;
        var fxrTd = null; //incase if Fxrtd is not selected by user use this parameter
        var settleDateValue = null;
        //MSSCUSTODY-3305 - bk_to_bk_info
        //var s = current.reason_description;

        if (current.trade_task_type == "GHSS Handler - Settle") {
            s = current.bk_to_bk_info;
        } else {
            s = current.reason_description;
        }
        var reasonDescription = s.toString().replaceAll('"', '\\"'); // Replace single & double quotes with backslash.
        var reason_description = reasonDescription.replace(/(?:\r\n|\r|\n)/g, " "); //Replace the new line characters with space.
        var remarksCase = reason_description.toUpperCase();
        //MSSCUSTODY-8617 Removal of Control Characters
        if (remarksCase != undefined && remarksCase != null && remarksCase != "") {
            remarksCase = remarksCase.replace(/\\./g, '');
            var controlRegex = /[\u0000-\u001F\u007F-\u009F\u061C\u200E\u200F\u202A-\u202E\u2066-\u2069]/g;
            remarksCase = remarksCase.replace(controlRegex, "");
            remarksCase = remarksCase.trim();
        }; //MSSCUSTODY-8617 Removal of Control Characters


        //MSSCUSTODY-3232 -- Updated the value as required for "Settle Trade" 
        if (current.auto_resume_indicator == "Y") {
            autoResumeIndicator = true;
        } else if (current.auto_resume_indicator == "N") {
            autoResumeIndicator = false;
        }

        if (current.advice == "Y") {
            adviceType = true;
        } else if (current.advice == "N") {
            adviceType = false;
        }

        if (current.advice == "")
            adviceType = "";

        // MSSCUSTODY - Advice field to be defaulted as Y if empty for GCS.
        if (current.advice == "Y") {
            adviceTypeGCS = true;
        } else if (current.advice == "N") {
            adviceTypeGCS = false;
        } else if (current.advice == "") {
            adviceTypeGCS = true;
        }

        if (current.suspend == "Y") {
            suspendType = true;
        } else if (current.suspend == "N") {
            suspendType = false;
        }
        if (current.collect_cancel_charge.toString().substring(0, 1) == "Y") {
            collectChargeIndicator = true;
        } else if (current.collect_cancel_charge.toString().substring(0, 1) == "N") {
            collectChargeIndicator = false;
        }

        if (current.value_date) {
            valDateValue = current.value_date;
        }
        if (current.settlement_date) {
            settleDateValue = current.settlement_date;
        }

        //For GC HK Widget -
        // if(current.gdi_indicator == "No Change"){
        // 	gdiVal = null;
        // }else if(current.gdi_indicator == "N"){
        // 	gdiVal = "N";
        // }

        //Handling for the reference incase of SWIFT trades
        var tradeReference = '';
        var sourceSystemTimeStamp = "";

        if (swiftSource.indexOf(sourceSystem) > -1) { //Limited to GCS Swift Trades
            var mkrTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            mkrTask.addEncodedQuery('trade_id.sys_id=' + current.trade_id + '^trade_task_type=Maker^active=false');
            mkrTask.orderByDesc('sys_created_on');
            mkrTask.setLimit(1);
            mkrTask.query();
            if (mkrTask.next()) {
                //Picking up the Actual Trade ID from wither SWIFT Linking Reference ID or Select SWIFT Linking Reference ID since one of the filed will hold the actual trade ID for linking
                if (mkrTask.swift_linking_reference != "") {
                    tradeReference = mkrTask.swift_linking_reference.getDisplayValue().toString(); //single trade 
                } else {
                    tradeReference = mkrTask.swift_linking_reference_id_ref.getDisplayValue().toString(); //multiple trade selected by user
                }

            }
        } else {
            tradeReference = current.ghss_trade_ref_id; // Actual Trades
        }
        //Handling for the reference incase of SWIFT trades


        var trade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
        trade.addQuery('trade_id', tradeReference);
        trade.query();
        if (trade.next()) {
            if (!current.amend_checker_decision) {
                // Case 1 - amend_checker_decision will be empty for generic triggers
                if ((gcsSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') > -1)) {
                    sourceSystemTimeStamp = trade.source_system_time_stamp_market_time.replace(' ', 'T').split('.')[0];
                } else if ((ghssSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') == -1)) {
                    sourceSystemTimeStamp = trade.source_system_time_stamp_market_time;
                }
            } else if (current.amend_checker_decision == 'AMEND_CONF') {
                // Case 2 - amend_checker_decision is AMEND_CONF set in CONF Handler Sunflow for Amend and CONF
                if ((gcsSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') > -1)) {
                    sourceSystemTimeStamp = current.sys_created_on.replace(' ', 'T').split('.')[0];
                } else if ((ghssSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') == -1)) {
                    sourceSystemTimeStamp = current.sys_created_on.replace(' ', 'T');
                }
            }
        }
        //HandlingsourceSystemTimeStamp  for the reference incase of SWIFT trades



        // request.setRequestHeader("Accept", "application/json");
        // request.setRequestHeader('Content-Type', 'application/json');

        // MSSOTIQUBE-1199 (calling GHSS_Helper script include directly from br)
        var ghss = new x_hsb11_mss_c_ghss.GHSS_Helper();
        var req;





        // MSSCUSTODY-4148 - Added check to set request body if source system is GHSS.
        if ((ghssSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('UK') == -1) && (trdOwningBusiness != 'GC HK')) {
            if (current.trade_task_type == "GHSS Handler - Resume") {

                //    request.setRequestBody('{ "request_type" : "resume_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "suspense_trade_status":"' + suspendType + '", "remark": "' + remarksCase + '", "reason_code": "' + current.reason_code.reason_code + '"  }');
                req = '{ "request_type" : "resume_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "suspense_trade_status":"' + suspendType + '", "remark": "' + remarksCase + '", "reason_code": "' + current.reason_code.reason_code + '"  }';

            } else if (current.trade_task_type == "GHSS Handler - On Hold") {

                req = '{ "request_type" : "hold_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "suspense_trade_status":"' + suspendType + '", "remark": "' + remarksCase + '", "reason_code": "' + current.reason_code.reason_code + '"  }';
                //  request.setRequestBody('{ "request_type" : "hold_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "suspense_trade_status":"' + suspendType + '", "remark": "' + remarksCase + '", "reason_code": "' + current.reason_code.reason_code + '"  }');

            } else if (current.trade_task_type == "GHSS Handler - Confirm") {

                //  request.setRequestBody('{ "request_type" : "confirm_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '"  }');
                req = '{ "request_type" : "confirm_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '"  }';

            } else if (current.trade_task_type == "GHSS Handler - Settle") {

                //   request.setRequestBody('{ "request_type" : "settle_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "remark": "' + remarksCase + '", "settle_indicator":"' + current.settlement_type.toString().substring(0, 1) + '", "auto_resume_indicator":"' + autoResumeIndicator + '"  }');
                req = '{ "request_type" : "settle_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "remark": "' + remarksCase + '", "settle_indicator":"' + current.settlement_type.toString().substring(0, 1) + '", "auto_resume_indicator":"' + autoResumeIndicator + '"  }';

            } else if (current.trade_task_type == "GHSS Handler - Cancel") {

                //  request.setRequestBody('{ "request_type" : "cancel_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "remark": "' + remarksCase + '", "cancellation_reference":"' + current.cancellation_reference + '", "cancellation_reason_code":"' + current.reason_code.reason_code + '", "collect_cancel_charge":"' + collectChargeIndicator + '", "cancelled_by_indicator":"' + current.cancel_by.toString().substring(0, 1) + '"  }');
                req = '{ "request_type" : "cancel_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "remark": "' + remarksCase + '", "cancellation_reference":"' + current.cancellation_reference + '", "cancellation_reason_code":"' + current.reason_code.reason_code + '", "collect_cancel_charge":"' + collectChargeIndicator + '", "cancelled_by_indicator":"' + current.cancel_by.toString().substring(0, 1) + '"  }';
            }
        } // MSSCUSTODY-4148 - Added check to set request body if source system is GCS.
        else if ((gcsSourceSystem.indexOf(sourceSystem) > -1) && ((trdOwningBusiness.indexOf('UK') > -1) || (trdOwningBusiness.indexOf('EU') > -1))) { //Added EU under MSSCUSTODY-8620
            if (current.trade_task_type == "GHSS Handler - Resume") {

                //   request.setRequestBody('{ "request_type" : "resume_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "suspense_trade_status":"' + suspendType + '", "remark": "' + remarksCase + '", "reason_code": "' + current.reason_code.reason_code + '"  }');
                req = '{ "request_type" : "resume_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "suspense_trade_status":"' + suspendType + '", "remark": "' + remarksCase + '", "reason_code": "' + current.reason_code.reason_code + '"  }';

            } else if (current.trade_task_type == "GHSS Handler - On Hold") {

                // request.setRequestBody('{ "request_type" : "hold_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "suspense_trade_status":"' + suspendType + '", "remark": "' + remarksCase + '", "reason_code": "' + current.reason_code.reason_code + '"  }');
                req = '{ "request_type" : "hold_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "suspense_trade_status":"' + suspendType + '", "remark": "' + remarksCase + '", "reason_code": "' + current.reason_code.reason_code + '"  }';

            } else if (current.trade_task_type == "GHSS Handler - Confirm") {

                //  request.setRequestBody('{ "request_type" : "confirm_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '","value_date":"' + valDateValue + '" }'); // MSSCUSTODY-4148 - Added Value Date in request body for Confirm widget.
                req = '{ "request_type" : "confirm_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '","value_date":"' + valDateValue + '" }';

            } else if (current.trade_task_type == "GHSS Handler - Settle") {

                // request.setRequestBody('{ "request_type" : "settle_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "remark": "' + remarksCase + '", "settle_indicator":"' + current.settlement_type.toString().substring(0, 1) + '", "auto_resume_indicator":"' + autoResumeIndicator + '","value_date":"' + valDateValue + '","settlement_date":"' + settleDateValue + '"  }'); // MSSCUSTODY-4148 - Added Value Date and Settlement Date in request body for Settle widget.
                req = '{ "request_type" : "settle_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "remark": "' + remarksCase + '", "settle_indicator":"' + current.settlement_type.toString().substring(0, 1) + '", "auto_resume_indicator":"' + autoResumeIndicator + '","value_date":"' + valDateValue + '","settlement_date":"' + settleDateValue + '"  }';

            } else if (current.trade_task_type == "GHSS Handler - Cancel") {

                if (current.fxr_td) {
                    //  request.setRequestBody('{ "request_type" : "cancel_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "remark": "' + remarksCase + '", "cancellation_reference":"' + current.cancellation_reference + '", "cancellation_reason_code":"' + current.reason_code.reason_code + '", "collect_cancel_charge":"' + collectChargeIndicator + '", "cancelled_by_indicator":"' + current.cancel_by.toString().substring(0, 1) + '","cancel_fx_indicator":"' + current.fxr_td.toString() + '"  }'); // MSSCUSTODY-4148 - Added FXRTD in request body for Cancel widget.
                    req = '{ "request_type" : "cancel_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "remark": "' + remarksCase + '", "cancellation_reference":"' + current.cancellation_reference + '", "cancellation_reason_code":"' + current.reason_code.reason_code + '", "collect_cancel_charge":"' + collectChargeIndicator + '", "cancelled_by_indicator":"' + current.cancel_by.toString().substring(0, 1) + '","cancel_fx_indicator":"' + current.fxr_td.toString() + '"  }';

                } else {
                    //   request.setRequestBody('{ "request_type" : "cancel_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "remark": "' + remarksCase + '", "cancellation_reference":"' + current.cancellation_reference + '", "cancellation_reason_code":"' + current.reason_code.reason_code + '", "collect_cancel_charge":"' + collectChargeIndicator + '", "cancelled_by_indicator":"' + current.cancel_by.toString().substring(0, 1) + '","cancel_fx_indicator":' + fxrTd + '  }'); // MSSCUSTODY-4148 - Removed FXRTD in request body for Cancel widget as optional.
                    req = '{ "request_type" : "cancel_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceTypeGCS + '", "remark": "' + remarksCase + '", "cancellation_reference":"' + current.cancellation_reference + '", "cancellation_reason_code":"' + current.reason_code.reason_code + '", "collect_cancel_charge":"' + collectChargeIndicator + '", "cancelled_by_indicator":"' + current.cancel_by.toString().substring(0, 1) + '","cancel_fx_indicator":' + fxrTd + '  }';
                }

            }
        }

        //GC HK Widgets
        else if ((ghssSourceSystem.indexOf(sourceSystem) > -1) && (trdOwningBusiness.indexOf('GC HK') > -1)) {
            if (current.trade_task_type == "GHSS Handler - Cancel") { //MSSCUSTODY-6087
                req = '{ "request_type" : "cancel_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "cancellation_reference":"' + current.cancellation_reference + '", "cancellation_reason_code":"' + current.reason_code.reason_code + '", "collect_cancel_charge":"' + collectChargeIndicator + '", "cancelled_by_indicator":"' + current.cancel_by.toString().substring(0, 1) + '", "fx_cx":"' + current.fx_cx.toString() + '", "gdi_indicator": "' + current.gdi_indicator.toString() + '" }';

            } else if (current.trade_task_type == "GHSS Handler - Settle") { //MSSCUSTODY-6090
                req = '{ "request_type" : "settle_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "remark": "' + remarksCase + '", "settle_indicator":"' + current.settlement_type.toString().substring(0, 1) + '","value_date":"' + valDateValue + '","settlement_date":"' + settleDateValue + '"  }';

            } else if (current.trade_task_type == "GHSS Handler - Confirm") { //MSSCUSTODY-6089
                req = '{ "request_type" : "confirm_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '"  }';

            } else if (current.trade_task_type == "GHSS Handler - On Hold") {
                req = '{ "request_type" : "hold_ghss", "servicenowid" : "' + current.sys_id + '", "maker" : "' + makerId + '", "checker" : "' + checkerId + '", "reference" : "' + tradeReference + '" , "last_update_date_time": "' + sourceSystemTimeStamp + '", "generate_advice":"' + adviceType + '", "suspense_trade_status":"' + suspendType + '", "remark": "' + remarksCase + '", "reason_code": "' + current.reason_code.reason_code + '"  }';
            }
        }

        ghss.ghssScriptedUpdateOutbound(req);

        //  var response = request.executeAsync();

    } catch (err) {
        gs.info("Unexpected error occurred :" + err);

    }


})(current, previous);
